<template><view class="page auth"><view class="brand">校园出游管理</view><view class="muted slogan">让集体出游更简单、更安全</view><view class="card"><view class="field"><text class="field-label">用户名</text><input v-model="form.username" class="input" placeholder="3-16位字母、数字或下划线" /></view><view class="field"><text class="field-label">密码</text><input v-model="form.password" class="input" password placeholder="8-64位密码" /></view><button class="primary-btn" :loading="loading" @click="login">登录</button><button class="secondary-btn" @click="goRegister">注册新账号</button></view></view></template>
<script setup lang="ts">import{reactive,ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{api}from'@/services/api';import{hasSession}from'@/services/session';import{useSessionStore}from'@/stores/session';const session=useSessionStore(),form=reactive({username:'',password:''}),loading=ref(false);onShow(()=>{if(hasSession())uni.switchTab({url:'/pages/home/home'})});const goRegister=()=>uni.navigateTo({url:'/pages/register/register'});async function login(){if(!form.username||form.password.length<8)return uni.showToast({title:'请填写正确的账号密码',icon:'none'});loading.value=true;try{const d=await api<any>('/auth/login','POST',form);session.save(d);uni.switchTab({url:'/pages/home/home'})}finally{loading.value=false}}</script>
<style scoped lang="scss">.auth{padding-top:18vh}.brand{font-size:54rpx;font-weight:800;color:$primary}.slogan{margin:16rpx 0 46rpx}</style>
